    "upd_ios_s1_title": "STEP 1 (OPTIONAL): Back up your save slot in Files",
    "upd_ios_s1_desc": "<strong>Optional — only if you already played:</strong> In game tap Floating Menu → Saves → Slot 1 → Rename → Export and save it in the iOS Files app.<br /><em>If installing for the first time, ignore this step and proceed directly to Step 2!</em>",
    "upd_ios_s2_title": "In-Game Floating Menu → Updates",
    "upd_ios_s2_desc": "Open the Floating Menu → tap <strong>Updates</strong>. Wait for the newest version (currently v4) to finish downloading at the bottom. You will see the download progress bar.",
    "upd_ios_s3_title": "Share IPA directly to SideStore",
    "upd_ios_s3_desc": "When download completes, 2 options appear below: <strong>Open in Files</strong> or <strong>Share IPA</strong>. Tap <strong>Share IPA</strong> → select <strong>SideStore</strong> from the share sheet to install directly! (Or choose Open in Files and import it manually into SideStore).",
    "upd_ios_s4_title": "Restore your save if needed",
    "upd_ios_s4_desc": "Launch the updated game. If progress is reset, tap the <strong>Floating Menu</strong> → <strong>Saves</strong> → <strong>Import from files</strong> → pick your exported save file from the Files app. All your characters, pearls, and progress are restored!",
    "ios_crit_banner_title": "CRITICAL: iOS 27 Required for No-PC Install",
    "ios_crit_banner_desc": "No-PC installation via SideInstaller ONLY works directly on <strong>iOS 27</strong>. On <strong>iOS 18–26</strong>, you MUST generate a pairing file on a PC once before SideInstaller can install apps. Or use Method 2 (PC with Sideloadly) for any iOS version.",
    "ios_s3_404_badge": "404 Error Fix",
    "ios_s3_404_note": "<strong>Why 404 occurs:</strong> The automated download in SideInstaller fails because the built-in repository is offline. Downloading standalone SideStore.ipa manually completely bypasses the 404 error!",
    "ios_s3_btn_gdrive": "Download SideStore.ipa (Google Drive)",
    "ios_s3_btn_github": "Download SideStore.ipa (GitHub Nightly)",
    "ios_s4_reassurance": "<strong>Security Dialog Note:</strong> Apple displays scary red warning buttons and 'Untrusted Developer' alerts by default for all sideloaded apps. This is standard iOS security behavior and 100% safe for SideStore.",
    "ios_pc_sideloadly_btn": "Download Sideloadly (PC / Mac)",
